// -1 = not in alphabet, -2 = skippable whitespace, -3 = '=' pad.
const int kInvalid    = -1;
const int kWhitespace = -2;
const int kPad        = -3;

int DecodeChar(unsigned char c) {
    if (c >= 'A' && c <= 'Z') { return c - 'A'; }
    if (c >= 'a' && c <= 'z') { return c - 'a' + 26; }
    if (c >= '0' && c <= '9') { return c - '0' + 52; }
